import{_ as t,c as r,o as d,ae as o}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse(`{"title":"Raise a Return","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-return","title":"Raise a Return","description":"Raise a new return (RMA) request for one item of one of the authenticated customer's orders.","query":"mutation CreateCustomerReturn(\\n  $orderId: Int!\\n  $orderItemId: Int!\\n  $rmaQty: Int!\\n  $resolutionType: String!\\n  $rmaReasonId: Int!\\n  $information: String\\n  $packageCondition: String\\n  $agreement: Boolean!\\n) {\\n  createCustomerReturn(\\n    input: {\\n      orderId: $orderId\\n      orderItemId: $orderItemId\\n      rmaQty: $rmaQty\\n      resolutionType: $resolutionType\\n      rmaReasonId: $rmaReasonId\\n      information: $information\\n      packageCondition: $packageCondition\\n      agreement: $agreement\\n    }\\n  ) {\\n    customerReturn {\\n      _id\\n      orderId\\n      orderIncrementId\\n      statusId\\n      statusTitle\\n      statusColor\\n      packageCondition\\n      information\\n      canClose\\n      canReopen\\n      isExpired\\n      item\\n      images\\n      messagesCount\\n      createdAt\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"orderId\\": 45,\\n  \\"orderItemId\\": 78,\\n  \\"rmaQty\\": 1,\\n  \\"resolutionType\\": \\"return\\",\\n  \\"rmaReasonId\\": 2,\\n  \\"information\\": \\"Item arrived damaged.\\",\\n  \\"packageCondition\\": \\"opened\\",\\n  \\"agreement\\": true\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createCustomerReturn\\": {\\n      \\"customerReturn\\": {\\n        \\"_id\\": 12,\\n        \\"orderId\\": 45,\\n        \\"orderIncrementId\\": \\"000000045\\",\\n        \\"statusId\\": 1,\\n        \\"statusTitle\\": \\"Pending\\",\\n        \\"statusColor\\": \\"#FDB022\\",\\n        \\"packageCondition\\": \\"opened\\",\\n        \\"information\\": \\"Item arrived damaged.\\",\\n        \\"canClose\\": true,\\n        \\"canReopen\\": false,\\n        \\"isExpired\\": false,\\n        \\"item\\": {\\n          \\"id\\": 30,\\n          \\"order_item_id\\": 78,\\n          \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n          \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n          \\"quantity\\": 1,\\n          \\"resolution\\": \\"return\\",\\n          \\"reason_id\\": 2,\\n          \\"reason\\": \\"Damaged product\\",\\n          \\"variant_id\\": null\\n        },\\n        \\"images\\": [],\\n        \\"messagesCount\\": 0,\\n        \\"createdAt\\": \\"2026-07-20T10:15:30+00:00\\",\\n        \\"updatedAt\\": \\"2026-07-20T10:15:30+00:00\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"item not returnable","cause":"The order item is outside its return window or already fully returned/canceled","solution":"Query returnableItems first and only raise a return for an eligible item and quantity"},{"error":"agreement required","cause":"The agreement field was not set to true","solution":"Send agreement as true to confirm the return terms"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The order does not exist or is not owned by the authenticated customer","solution":"Only order IDs belonging to the logged-in customer can be used"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/mutations/create-return.md","filePath":"api/graphql-api/shop/returns/mutations/create-return.md"}`),n={name:"api/graphql-api/shop/returns/mutations/create-return.md"};function a(i,e,s,c,u,l){return d(),r("div",null,e[0]||(e[0]=[o('<h1 id="raise-a-return" tabindex="-1">Raise a Return <a class="header-anchor" href="#raise-a-return" aria-label="Permalink to &quot;Raise a Return&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>createCustomerReturn</code> mutation raises a new return (RMA) request for one item of one of the customer&#39;s orders. The item must be return-eligible — check it with <a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html"><code>returnableItems</code></a> first. The requested quantity (<code>rmaQty</code>) is capped server-side by the quantity the customer is actually allowed to return. The return starts in a <code>Pending</code> status.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the order the item belongs to.</td></tr><tr><td><code>orderItemId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the order item being returned — from <code>returnableItems</code>.</td></tr><tr><td><code>rmaQty</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Quantity to return. Capped server-side by the returnable quantity.</td></tr><tr><td><code>resolutionType</code></td><td><code>String!</code></td><td>✅ Yes</td><td><code>return</code> or <code>cancel_items</code>.</td></tr><tr><td><code>rmaReasonId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the chosen return reason — from <code>returnReasons</code>.</td></tr><tr><td><code>information</code></td><td><code>String</code></td><td>❌ No</td><td>Free-text note about the return.</td></tr><tr><td><code>packageCondition</code></td><td><code>String</code></td><td>❌ No</td><td>Reported package condition, e.g. <code>opened</code>.</td></tr><tr><td><code>agreement</code></td><td><code>Boolean!</code></td><td>✅ Yes</td><td>Must be <code>true</code> to confirm the return terms.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>customerReturn._id</code></td><td><code>Int!</code></td><td>Numeric return ID.</td></tr><tr><td><code>customerReturn.orderId</code></td><td><code>Int!</code></td><td>Id of the order the item belongs to.</td></tr><tr><td><code>customerReturn.orderIncrementId</code></td><td><code>String!</code></td><td>Human-readable order number.</td></tr><tr><td><code>customerReturn.statusId</code></td><td><code>Int!</code></td><td>Numeric status id — <code>1</code> (Pending) for a fresh return.</td></tr><tr><td><code>customerReturn.statusTitle</code></td><td><code>String!</code></td><td>Status label.</td></tr><tr><td><code>customerReturn.statusColor</code></td><td><code>String!</code></td><td>Hex color for the status badge.</td></tr><tr><td><code>customerReturn.packageCondition</code></td><td><code>String</code></td><td>Reported package condition.</td></tr><tr><td><code>customerReturn.information</code></td><td><code>String</code></td><td>The note supplied when raising the return.</td></tr><tr><td><code>customerReturn.canClose</code></td><td><code>Boolean</code></td><td>Whether the return can be closed.</td></tr><tr><td><code>customerReturn.canReopen</code></td><td><code>Boolean</code></td><td>Whether the return can be reopened.</td></tr><tr><td><code>customerReturn.isExpired</code></td><td><code>Boolean</code></td><td>Whether the return is past its action window.</td></tr><tr><td><code>customerReturn.item</code></td><td><code>Object</code></td><td>The returned item — <code>id</code>, <code>order_item_id</code>, <code>sku</code>, <code>name</code>, <code>quantity</code>, <code>resolution</code>, <code>reason_id</code>, <code>reason</code>, <code>variant_id</code>. Query bare (a JSON object).</td></tr><tr><td><code>customerReturn.images</code></td><td><code>Array</code></td><td>Attached images (<code>id</code>, <code>path</code>, <code>url</code>). Empty on a JSON-created return. Query bare (a JSON array).</td></tr><tr><td><code>customerReturn.messagesCount</code></td><td><code>Int!</code></td><td>Number of conversation messages — <code>0</code> for a fresh return.</td></tr><tr><td><code>customerReturn.createdAt</code></td><td><code>DateTime!</code></td><td>Return creation timestamp.</td></tr><tr><td><code>customerReturn.updatedAt</code></td><td><code>DateTime!</code></td><td>Return last update timestamp.</td></tr></tbody></table><p>Attaching image files to a return is REST-only, through a multipart <code>images[]</code> field — a JSON GraphQL request cannot carry a file. Raise the return here, then upload the images over REST if the shopper attached any.</p><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html">List Returnable Items</a></li><li><a href="/api/graphql-api/shop/returns/queries/list-return-reasons.html">List Return Reasons</a></li><li><a href="/api/graphql-api/shop/returns/mutations/cancel-return.html">Cancel a Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>',12)]))}const p=t(n,[["render",a]]);export{h as __pageData,p as default};
